@JvmName("step130")
fun step130(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 77
}
data class Pair131<A, B>(val first: A, val second: B)

fun combine131(left: Int, right: Int): Pair131<Int, Int> {
    return Pair131(left + 84, right + 50)
}
class Counter132 {
    var current: Int by Delegates.observable(91) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
